// Recalcula automáticamente competencias en la hoja, sin duplicar el bonificador.
const SKILL_ABILITY=[1,4,3,0,5,3,4,5,3,4,3,4,5,5,3,1,1,4];
function numericField(key,fallback=0){const el=document.querySelector(`[data-char="${key}"]`);const n=Number(el?.value);return Number.isFinite(n)?n:fallback;}
function formatBonus(n){return n>=0?'+'+n:String(n);}
function recalculateSkillBonuses(){
 const score=Array.from({length:6},(_,i)=>numericField('ability_'+i,10));
 const mod=score.map(n=>Math.floor((n-10)/2));
 const prof=numericField('profBonus',2);
 score.forEach((_,i)=>{const el=document.querySelector(`[data-char="abilitymod_${i}"]`);if(el)el.value=formatBonus(mod[i]);});
 SKILL_ABILITY.forEach((ability,i)=>{
  const dot=document.querySelector(`[data-char="skillprof_${i}"]`);
  const number=document.querySelector(`[data-char="skill_${i}"]`);
  if(number)number.value=formatBonus(mod[ability]+(dot?.checked?prof:0));
 });
 ['str','dex','con','int','wis','cha'].forEach((k,i)=>{
  const dot=document.querySelector(`[data-char="saveprof_${k}"]`);
  const number=document.querySelector(`[data-char="save_${k}"]`);
  if(number)number.value=formatBonus(mod[i]+(dot?.checked?prof:0));
 });
}
function setupAutoSkills(){
 const keys=['profBonus',...Array.from({length:6},(_,i)=>'ability_'+i),...Array.from({length:18},(_,i)=>'skillprof_'+i),...'str dex con int wis cha'.split(' ').map(k=>'saveprof_'+k)];
 keys.forEach(k=>{const el=document.querySelector(`[data-char="${k}"]`);if(el)el.addEventListener('input',()=>{recalculateSkillBonuses();saveCharacter();});});
 recalculateSkillBonuses();saveCharacter();
}

loadCharacter();
bindCharacter();
setupAutoSkills();
addSheetSpellLinks();
renderDeathSaves();
init();
initializeRogerHealth();
renderInitiative();


// --- Visor del PDF editable real ---
(function bindNativePdfViewer(){
  const pdfPath='assets/Alak-Hul-N3-editable.pdf';
  if(!frame) return;
  buttons.forEach(btn=>btn.addEventListener('click',()=>{
    buttons.forEach(b=>b.classList.toggle('active',b===btn));
    const page=btn.dataset.pdfPage;
    // El visor nativo recibe el destino de página mediante el fragmento PDF.
    frame.src=`${pdfPath}#page=${page}&zoom=page-width&toolbar=1&navpanes=0`;
  }));
})();
